import math


def skill_score(pi_theta, dataset, skill):
    total = 0.0
    for x, y in dataset:
        p = pi_theta.logprob(y, prompt=x, skill=skill)
        total += math.log(max(p, 1e-12))
    return total / max(len(dataset), 1)


def pick_best(skills, dataset, pi_theta):
    return max(skills, key=lambda s: skill_score(pi_theta, dataset, s))

def reflective_loop(skill, dataset, pi_theta, edit_fn, rounds=4):
    history = []
    for k in range(rounds):
        failures = []
        for x, y in dataset:
            pred = pi_theta.generate(x, skill=skill)
            if pred.strip() != y.strip():
                failures.append((x, y, pred))
        history.append(len(failures))
        if not failures:
            break
        skill = edit_fn(skill, failures)
    return skill, history
